import SwiftUI
import AtiCleanerCore

@MainActor final class LargeVM:ObservableObject{@Published var files:[LargeFileResult]=[];@Published var scanning=false;@Published var minSize:Int64=100*1024*1024;@Published var root=FileManager.default.homeDirectoryForCurrentUser.path
func scan(){guard !scanning else{return};scanning=true;Task{let r=root;let m=minSize;let found=await Task.detached{LargeFileScanner().scan(root:URL(fileURLWithPath:r),minSize:m,progress:{_ in},isCancelled:{false})}.value;files=found;scanning=false}}}
struct LargeFilesView:View{@StateObject private var vm=LargeVM();var body:some View{VStack(alignment:.leading,spacing:16){PageHeader(icon:"doc.richtext",title:"Büyük Dosyalar",subtitle:"Boyut eşiğine ve konuma göre büyük dosyaları bulun.",tint:Theme.large,actionTitle:"Tara",action:vm.scan);HStack{Picker("Minimum Dosya Boyutu",selection:$vm.minSize){ForEach([10,50,100,250,500],id:\.self){n in Text("\(n) MB").tag(Int64(n*1024*1024))};Text("1 GB").tag(Int64(1024*1024*1024));Text("2 GB").tag(Int64(2*1024*1024*1024))};Picker("Tarama Konumu",selection:$vm.root){Text("Ev Dizini").tag(FileManager.default.homeDirectoryForCurrentUser.path);Text("Belgeler").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents").path);Text("İndirilenler").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Downloads").path);Text("Masaüstü").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Desktop").path);Text("Filmler").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Movies").path)}}.padding(12).background(RoundedRectangle(cornerRadius:12).fill(Color(nsColor:.controlBackgroundColor)));if vm.scanning{ProgressView("Dosyalar taranıyor…")}else if vm.files.isEmpty{VStack(spacing:18){ReadyRing(icon:"doc.richtext.fill",title:"Taramaya Hazır",detail:vm.minSize.formattedBytes+"+",tint:Theme.large);HStack{InfoTile(icon:"film.fill",title:"Videolar",subtitle:"Büyük medya dosyaları",tint:Theme.large);InfoTile(icon:"archivebox.fill",title:"Arşivler",subtitle:"ZIP ve arşivler",tint:Theme.large);InfoTile(icon:"externaldrive.fill",title:"Disk İmajları",subtitle:"DMG ve benzeri",tint:Theme.large);InfoTile(icon:"doc.fill",title:"Belgeler",subtitle:"Büyük belgeler",tint:Theme.large)}.frame(maxWidth:840)}.frame(maxWidth:.infinity)}else{List(vm.files){f in HStack{Text(f.name);Spacer();Text(f.size.formattedBytes).monospacedDigit().foregroundStyle(.secondary)}}}}.padding(24)}}
